/* --- Battute: 12 per personaggio (da maya.txt) --- */
(function(){
const TOPX_MY={
my_nikte:[
["Chi sei e che fai?","Nikte’, trent’anni, contadina. Mi occupo della milpa con mio marito: semino mais, fagioli e zucca, tengo i tacchini e un paio di alveari di api senza pungiglione. Mi sveglio col buio per accendere il fuoco e macinare, e finisco quando il fuoco si abbassa."],
["Cosa coltivate?","Il mais prima di tutto, poi fagioli, zucca e peperoncino. Piantiamo insieme mais e fagioli: i fagioli si arrampicano sullo stelo, e la zucca fa ombra alla terra. Ogni anno tagliamo e bruciamo un pezzo di bosco per fare il campo nuovo, e lasciamo riposare quello vecchio."],
["Come si prepara il mais?","Si fanno bollire i chicchi con un po’ di calce, si lasciano a riposo una notte e poi si macinano su una pietra, il metate. Con la pasta si fanno tortillas sul comal, tamales avvolti in foglie e una bevanda calda, l’atole. Nessuna casa maya sta senza una pietra da macina."],
["Com’è fatta la casa?","Pali di legno infilati nel terreno, pareti di rami intrecciati coperte di fango e un tetto di foglie di palma. Una stanza per dormire, una per cucinare, e il cortile con un orto e un pezzo di terra per gli alberi da frutta. Quando piove forte, il tetto canta."],
["Cosa mangiate?","Tortillas, fagioli, zucca, salsa di peperoncino, un po’ di frutta e a volte carne di tacchino o di cervo. Il miele delle mie api lo uso per addolcire le bevande e per fare le medicine. Il cacao è per le feste e per i signori: io l’ho assaggiato una volta, e ancora ne parlo."],
["Come vi vestite?","Un telo di cotone attorno alla vita per gli uomini, gonna e camicia per le donne; il cotone lo filo io con il fuso. Qualcuno si fa appiattire la fronte da piccolo o limare i denti per bellezza, e molti portano collane di giada o di conchiglia. Anche i bambini girano scalzi."],
["Cos’è El Mirador?","La grande città qui accanto, dove si costruiscono piramidi altissime: la più grande, La Danta, sarà alta circa settanta metri. Strade rialzate di pietra bianca portano a Nakbe e ad altre città. Quando hanno bisogno di mani, i nostri signori chiamano anche noi."],
["Chi comanda?","Un re, l’ajaw, che discende da una famiglia antica e ha il compito di parlare con gli dèi e di tenere in ordine il mondo. Noi gli portiamo parte del raccolto e un po’ di lavoro; lui ci protegge e organizza le feste. Se è un buon re, ci conviene."],
["In cosa credete?","Che il mondo ha tre piani: il cielo, la terra e Xibalbá, il mondo di sotto. Una ceiba enorme li unisce e noi lasciamo offerte di copal, un incenso, ai suoi piedi. Chaak porta la pioggia e il dio del mais muore e rinasce a ogni raccolto, come il mio mais."],
["Cos’è la stanza dipinta?","A San Bartolo, poco lontano, dipingono una stanza con il dio del mais e la creazione del mondo, intorno al 100 a.C.; dicono che qualcuno la ritroverà dopo duemila anni, nel 2001. Io la conosco solo per sentito dire. Un muro dipinto che resiste tanto vale più di un raccolto."],
["Dove vado dopo?","Verso ovest, dove le colline sono piene di cascate e un giorno ci sarà un re che sale al trono da bambino: Palenque. Segui il sentiero e chiedi dell’acqua, che laggiù è dappertutto. Porta con te un po’ di tortillas, che sono il miglior passaporto."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e se ripassi ti faccio assaggiare il miele delle mie api. Non toccare la pietra da macina, che è mia. State bene, e che la pioggia arrivi in tempo!"]
],
my_pakal:[
["Chi sei e che fai?","Pakal, figlio di Lady Sak K’uk’, ajaw di Palenque dal 615. Il mio nome significa \"scudo\": un re deve difendere la città, tenere buoni rapporti con gli dèi e far costruire. Sono sposato con Lady Tz’akb’u Ajaw e ho due figli, K’inich Kan B’alam e K’inich K’an Joy Chitam, che prenderanno il mio posto."],
["Com’è stato salire al trono a dodici anni?","Strano: mi hanno messo una fascia sulla fronte, e tutti, adulti compresi, si sono inchinati. In realtà mia madre ha tenuto il timone per anni, e io ho imparato guardando. Palenque era in un momento difficile, ma una città con un buon re, anche giovane, torna a respirare."],
["Com’è Palenque?","Una città fra colline coperte di foresta e piena d’acqua: il ruscello Otolum scorre sotto le piazze e fa cascate dappertutto. Chiamiamo la città Lakamha’, \"grande acqua\". Con i nostri scultori e stuccatori, le pareti dei templi sembrano arazzi di pietra dipinta."],
["Com’è fatto il tuo Palazzo?","Cortili, gallerie e una torre a più piani da cui, dicono, si osserva il cielo, anche se non tutti sono d’accordo. Ci sono anche bagni di vapore e latrine, collegati a canali che portano l’acqua. Un re che non sa dove far scorrere l’acqua non governa bene."],
["Come si veste un re?","Con tutto ciò che luccica: giada, piume di quetzal, conchiglie e pelli di giaguaro. Il copricapo può pesare quanto un bambino, e per questo si tiene la testa dritta. Dal giorno in cui ti incoronano, la giada è il tuo secondo vestito."],
["Cosa si mangia a corte?","Tortillas, tamales, fagioli, carne di tacchino e di cervo, e soprattutto cacao: una bevanda calda, amara e spumosa, con peperoncino e miele, che si versa da un vaso all’altro per fare la schiuma. Bere cacao è un po’ come bere ricchezza, ed è per le grandi occasioni."],
["Chi scrive la storia?","Gli scribi e gli scultori, che scrivono con glifi sulle pareti, sulle stele e sui libri. Nei nostri testi ci sono la mia nascita, la mia incoronazione e le date dei grandi eventi, tutto contato con precisione nel calendario. Una storia senza date è solo una chiacchiera."],
["Cos’è il Tempio delle Iscrizioni?","Una piramide a nove gradoni che ho cominciato a far costruire intorno al 675 come mia tomba, con un tempio in cima e grandi pannelli di glifi. Mio figlio Kan B’alam la finirà dopo di me. Chi la leggerà un giorno saprà tutto di me, dalle date alla genealogia."],
["Cosa c’è sul coperchio del sarcofago?","Io, che cado nelle fauci del mondo di sotto, e sopra di me l’albero del mondo con un uccello sul ramo più alto: è l’immagine del viaggio che ogni re fa per rinascere. Qualcuno, un giorno, vedrà in quell’immagine una navicella spaziale: io vedo un albero, e gli studiosi, per fortuna, anche."],
["Cosa succederà alla tua tomba?","Nel 1952 un archeologo messicano, Alberto Ruz Lhuillier, dopo anni di lavoro solleverà una lastra, scenderà una scala piena di pietre e aprirà la cripta. Troverà un uomo con una maschera di mosaico di giada, ricoperto di polvere rossa, e quella maschera finirà in un museo. Una tomba aperta dopo più di milleduecento anni: spero che chi la apre sappia cosa sta guardando."],
["Dove vado dopo?","A Tikal, nel cuore della foresta, dove proprio in questi anni sale al trono un re, Jasaw Chan K’awiil, che dovrà rimettere in piedi la sua città dopo un lungo periodo difficile. Segui il sentiero verso est e cerca le piramidi che spuntano fra gli alberi. È un’altra città, e un altro modo di regnare."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che una città vale quanto la memoria che lascia. Se ripassi, ti faccio salire sul Tempio delle Iscrizioni, ma lascia perdere la tomba. State bene, e che gli dèi vi accompagnino!"]
],
my_jasaw:[
["Chi sei e che fai?","Jasaw Chan K’awiil, re di Tikal dal 682, figlio di Nuun Ujol Chaak. Faccio costruire templi, firmo alleanze, guido la guerra quando serve e parlo con gli antenati. Gli studiosi di domani, per prendermi in giro, mi chiameranno anche \"Ah Cacao\"."],
["Cos’era successo a Tikal prima di te?","Nel 562 la città subì una grave sconfitta contro un’alleanza guidata da Calakmul, e per circa centotrent’anni non si scolpirono quasi più monumenti con date. Era un lungo silenzio, un po’ come un libro con le pagine strappate. Quando salii al trono, il mio compito era riscrivere quelle pagine."],
["Chi era Siyaj K’ak’?","Un condottiero che nel 378, secondo le nostre date, arrivò a Tikal da lontano, forse da Teotihuacan, la grande città del Messico centrale. Quel giorno morì anche il re di allora, e da quel momento arrivarono modi e oggetti nuovi. Gli studiosi di domani discuteranno ancora se fu una conquista o un’alleanza: io dico che fu tutte e due."],
["Come hai vinto Calakmul?","Nel 695, con un esercito di guerrieri di Tikal, sconfissi il re di Calakmul e ne presi dei prigionieri. La scena sarà scolpita nelle travi di legno sopra la porta del mio tempio. Una vittoria si ricorda meglio se si può guardare, non solo ascoltare."],
["Com’è Tikal?","Grandi piazze con le piramidi, i palazzi, serbatoi per l’acqua piovana, strade rialzate che attraversano il bosco e un mercato dove si trova di tutto. Ci vivono decine di migliaia di persone, e a me sembrano sempre troppo poche per una città così. Le scimmie urlatrici, invece, sono un coro che non si può zittire."],
["Cosa sono i Templi I e II?","Il Tempio I, alto circa quaranta metri, sarà la mia tomba; il Tempio II, di fronte, è per mia moglie, Lady Lahan Unen Mo’. Gli archeologi del Novecento troveranno nella mia tomba giada, pelli di giaguaro e ossa incise con scene di canoe. Spero che trovino anche il mio senso dell’umorismo."],
["Come si costruisce una piramide?","Si taglia il calcare con strumenti di pietra, si trasporta a mano, perché non abbiamo né ruote per i carri né animali da soma, e si ricopre di stucco, fatto con calce, che si ottiene bruciando la pietra. Poi si dipinge di rosso. Servono migliaia di persone e anni di lavoro: una piramide è fatta soprattutto di pazienza."],
["Cosa sono i gruppi gemelli?","Due piramidi uguali una di fronte all’altra, con un recinto e una stele, che costruiamo per celebrare la fine di un k’atun, un periodo di venti anni del nostro calendario. Sono una nostra specialità: nessun’altra città ne ha tante. Fra l’altro, è un buon modo per far passare il tempo con una festa."],
["Cosa si vende al mercato?","Cacao, sale, cotone, ossidiana per le lame, giada, conchiglie, piume di quetzal, miele, pelli e ceramiche dipinte. Il cacao serve anche come moneta, e certi mercanti arrivano da molto lontano. Chi sa contrattare, qui, non muore di fame."],
["Cosa succederà alle travi di legno dei templi?","Nel 1877 uno svizzero, Gustav Bernoulli, ne porterà via alcune: le vedrai a Basilea, in un museo, mentre a Tikal ci saranno delle copie. Il legno di sapodilla è così duro che ha resistito più di mille anni. Mi lusinga che qualcuno attraversi un oceano per guardarlo, ma preferirei che restassero a casa."],
["Dove vado dopo?","A nord-ovest, lungo il grande fiume Usumacinta, dove una regina di nome Lady Xook ha fatto scolpire i suoi architravi. È una città su un’ansa del fiume, con un re che regna da più di sessant’anni. Porta con te un po’ di cacao per presentarti bene."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che una città che torna in piedi ha più valore di una che non è mai caduta. Se ripassi, ti faccio salire sul Tempio I: la vista è migliore delle mie battute. State bene, e che gli antenati vi proteggano!"]
],
my_xook:[
["Chi sei e che fai?","Lady Xook, prima sposa del re di Yaxchilán, con il titolo di \"kalo’mte’\", un rango alto, quasi da sovrana. Seguo i riti con mio marito, tengo i rapporti con le famiglie nobili e vigilo sui tessuti della corte. In una città maya, una regina non è mai un ornamento."],
["Come sei diventata moglie del re?","In una famiglia nobile i matrimoni uniscono città e dinastie, e il mio ha unito lui e la mia casata. Itzamnaaj B’alam, detto Giaguaro Scudo, è re dal 681 e regnerà per più di sessant’anni. Un matrimonio così lungo si fa con pazienza: la mia."],
["Com’è Yaxchilán?","Una città su un’ansa a ferro di cavallo del fiume Usumacinta, che la protegge su tre lati e porta le canoe con le merci. Salendo dalla riva ci sono piazze a terrazze, templi, stele e il Labirinto sulla collina. Quando il fiume cresce, è più bello e anche più pericoloso."],
["Cos’è questa Struttura 23?","Un edificio con tre porte, dedicato a me, con tre architravi di pietra scolpita sopra gli ingressi. Gli studiosi di domani li chiameranno 24, 25 e 26. Gli scultori hanno firmato le lastre: un artista che firma sa quanto vale."],
["Cosa mostra l’architrave 24?","Me, inginocchiata, che tiro una corda con spine attraverso la lingua, mentre il re tiene una torcia, in un rito del 709. È un’offerta di sangue ai nostri antenati, e per noi un atto sacro, non una crudeltà. Il sangue unisce i vivi e i morti."],
["E l’architrave 25?","Mostra una visione: un grande serpente con la bocca aperta da cui esce un antenato armato. Per noi i morti non spariscono, tornano quando li si chiama con il rito giusto. Io, in quel momento, non guardavo l’artista: guardavo il serpente."],
["Come si veste una dama di corte?","Con una veste lunga di cotone, a volte ricamata a motivi geometrici, un copricapo annodato con fiori, e collane e orecchini di giada. I colori si fanno con ematite per il rosso, fuliggine per il nero, indaco per il blu: c’è anche il \"blu maya\", che non sbiadisce. Vestirsi bene è un modo di essere rispettati."],
["Come si tesse?","Con un telaio a cintura: una estremità si lega a un albero o a un palo e l’altra alla vita della tessitrice, e si tende il filo andando avanti e indietro. Le donne lavorano fianco a fianco e si raccontano storie. I tessuti sono anche un tributo che le città pagano a quelle più potenti."],
["Chi comanda in una città maya?","Il re, l’ajaw, con i nobili, i capi guerrieri e i sacerdoti, e a volte anche le donne di rango come me. Le città sono rivali e alleate, e si sposano fra loro per accordi di pace. Una regina che sa leggere le alleanze vale una piccola armata."],
["Dove finiranno i tuoi architravi?","Un inglese, Alfred Maudslay, nel 1882 e 1883 farà tagliare i miei architravi 24 e 25 e li porterà a Londra, dove si vedono al British Museum; il 26 è a Città del Messico. È un lungo viaggio per una regina. Almeno, mi guarderanno in tanti."],
["Dove vado dopo?","A sud-est, in una valle verde dell’Honduras, dove c’è Copán, la città degli scultori e degli scribi. Lì, a una scalinata, la storia di un’intera dinastia è scritta con duemila glifi. Chiedi di uno scriba: ti spiegherà come si scrive e come si conta."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che un filo ben teso tiene insieme una casa, come un’alleanza tiene insieme una città. Se ripassi, ti mostro come si tende il telaio. State bene, e che gli antenati vi guardino con benevolenza!"]
],
my_chankin:[
["Chi sei e che fai?","Chan K’in, quarant’anni, scriba e astronomo. Scrivo e dipingo glifi su pareti, stele e libri, calcolo le date e osservo il cielo con altri scribi. In questa città un re senza scriba è un re senza memoria."],
["Come si scrive in maya?","Con circa ottocento segni, i glifi: alcuni valgono una parola, altri una sillaba, e si combinano come i mattoncini. Si legge a coppie di colonne, da sinistra a destra e dall’alto al basso. Ci vogliono anni per imparare, e tutta la vita per scrivere bene."],
["Come si contano i numeri?","In base venti, con tre segni soltanto: un punto vale uno, una barra vale cinque e una conchiglia vale zero. Così posso scrivere numeri enormi con pochissimi segni. Il nostro zero, una conchiglia vuota, è una delle mie invenzioni preferite: ha il nome di \"niente\" e vale moltissimo."],
["Come funziona il calendario?","Usiamo più calendari insieme: il Tzolk’in di 260 giorni, il Haab’ di 365 e, combinati, la Ruota Calendariale di circa cinquantadue anni. Per contare periodi più lunghi c’è il Lungo Computo, che parte da una data mitica, il 3114 a.C. Chi sa leggere un’iscrizione sa sempre che giorno era, e di che anno."],
["Cos’è la Scalinata dei Geroglifici?","Una scalinata di sessantatré gradini coperta da circa 2200 glifi: il testo più lungo di tutti i Maya. Racconta la storia della nostra dinastia, dalla fondazione, nel 426, di K’inich Yax K’uk’ Mo’ in poi. La finirà intorno al 755 il re K’ak’ Yipyaj Chan K’awiil, con statue di re seduti sui gradini."],
["Chi era 18 Coniglio?","Waxaklajuun Ub’aah K’awiil, il nostro tredicesimo re, che regnò dal 695 al 738 e fece scolpire stele bellissime e un campo da palla. Nel 738 venne catturato e ucciso da K’ak’ Tiliw Chan Yopaat, re di Quiriguá, un tempo suo vassallo: fu un colpo duro per Copán. Ma la dinastia andò avanti, e la scalinata ne racconta ancora la storia."],
["Come si fanno i libri?","Si prende la corteccia interna di un albero di fico, la si batte fino a farne una striscia sottile e la si copre di calce; poi si ripiega a fisarmonica, e si dipinge con un pennello di peli. Le copertine sono di pelle di giaguaro, quando si può. Un libro ben fatto è più resistente di quanto sembri, ma teme il fuoco."],
["E i colori?","Il rosso si fa con ematite o cinabro, il nero con la fuliggine, il giallo con ocra e il blu con indaco mescolato a un’argilla speciale: è il \"blu maya\", che non sbiadisce. Ci vogliono mani sicure, perché ogni errore è difficile da cancellare. Di colori sbagliati non si muore, ma si ride per mesi."],
["Come scolpiscono i vostri artisti?","Con scalpelli di selce e martelli di pietra su una pietra vulcanica, tenera da lavorare e dura da consumare. Prima si disegna con un colore rosso sul blocco, poi si scolpisce, poi si copre di stucco e si dipinge. Noi scribi decidiamo cosa scrivere: gli scultori, come scriverlo bene."],
["Come si diventa scriba?","Si nasce in una famiglia nobile e si comincia da ragazzi, imparando i glifi, i numeri e i calendari da un maestro. I nostri patroni sono due scimmie, i fratelli Hun Batz e Hun Chuen, dèi dell’arte e della scrittura. C’è chi dice che una scimmia scriva meglio di certi re, e a volte ha ragione."],
["Dove vado dopo?","A nord, in Yucatán, a Chichén Itzá, una città di pietra bianca con una piramide che a certi giorni dell’anno \"mostra\" un serpente. Molti anni dopo la nostra epoca, quando le città del sud si saranno svuotate. Porta con te un po’ d’acqua: laggiù i fiumi sono rari."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che ciò che è scritto bene dura più di chi lo scrive. Se ripassi, ti insegno a disegnare un glifo. State bene, e che il tempo vi sia lungo!"]
],
my_balam:[
["Chi sei e che fai?","B’alam, ventiquattro anni, giocatore di palla. Mi alleno ogni mattina sul Gran Campo e gioco nelle feste: è un onore, ma anche un lavoro duro. Il mio nome vuol dire \"giaguaro\", e il giaguaro non si lamenta delle ginocchia."],
["Come si gioca?","Con una palla di gomma piena, pesante, che non si può toccare con le mani: si colpisce con i fianchi, le cosce e gli avambracci, e si cerca di farla passare in un anello di pietra. Si gioca in due squadre, su un campo con alte pareti. Gli studiosi di domani chiameranno il gioco \"pok ta pok\", ma noi lo chiamiamo semplicemente \"la partita\"."],
["Perché si gioca?","È un gioco e anche un rito: nel Popol Vuh i Gemelli Eroi, Hunahpú e Xbalanqué, sfidano a palla i signori di Xibalbá e li battono. Si gioca anche per festeggiare, per sfidarsi, per scommettere e, a volte, per risolvere dispute. Un buon match vale una piccola guerra, ma senza lutti."],
["È vero che chi perde viene sacrificato?","Non sempre, e gli studiosi non sono d’accordo su chi fosse coinvolto. Sulle pareti del Gran Campo ci sono rilievi con una scena di decapitazione, e c’è chi la legge come un sacrificio rituale, forse di chi perdeva, forse di altri. Io, per sicurezza, preferisco vincere."],
["Com’è il Gran Campo?","Il più grande di tutto il nostro mondo: circa 168 metri di lunghezza e 70 di larghezza, con pareti alte più di otto metri e due anelli di pietra molto in alto. Chi parla da un’estremità sente la voce all’altra, dicono. Per un giocatore, è una distanza spaventosa."],
["Cos’è El Castillo?","La piramide di Kukulcán, il serpente piumato. Ha quattro scalinate di novantuno gradini: con la piattaforma in cima fanno trecentosessantacinque, come i giorni dell’anno. Nei giorni dell’equinozio, nel tardo pomeriggio, un’ombra a zigzag scende lungo la scalinata nord fino alla testa di serpente scolpita."],
["Cos’è il cenote sacro?","Un enorme pozzo naturale con pareti a picco e acqua verde, in una pianura dove i fiumi sono rari: da qui la città prende l’acqua e il nome. Vi si portano offerte di giada, di oro, di legno e di tessuto per gli dèi della pioggia. Sul fondo, un giorno, qualcuno le ritroverà."],
["Cosa mangi e bevi da atleta?","Tortillas, fagioli, un po’ di carne di tacchino e soprattutto il pozol, una bevanda fredda di mais macinato che si porta in una zucca e dà energia per ore. Prima delle partite, a volte, una tazza di cacao spumoso. Un giocatore digiuno è una palla sgonfia."],
["Da dove arrivano certi templi con guerrieri e serpenti?","Da lontano, o almeno ne portano lo stile: in città si vedono serpenti piumati, guerrieri in fila, colonne con figure e statue distese che tengono un vassoio. Gli studiosi di domani discuteranno su quanto vengano dal Messico centrale e quanto siano nostri. Io dico che Chichén sa prendere il meglio da tutti."],
["Cos’è successo alle città del sud?","Dall’800 circa si svuotano una dopo l’altra: gli studiosi pensano a siccità, guerre e crisi politiche, tutte insieme. L’ultima data del Lungo Computo viene incisa a Toniná, nel 909. Molti profughi arrivano qui al nord con una storia di piogge che non vengono."],
["Dove vado dopo?","Verso la costa orientale, dove i mercanti e le grandi canoe partono per l’Honduras: Tulum, una città murata su una scogliera sopra il mare. Se ci arrivi al tramonto, il mare è color di rosa. Porta del mais tostato, che i marinai lo apprezzano."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che una partita si gioca con il corpo, ma si vince con la testa. Se ripassi, ti insegno a colpire la palla con il fianco senza perdere l’equilibrio. State bene, e che la palla vi sia propizia!"]
],
my_chakkan:[
["Chi sei e che fai?","Chak Kan, quarantadue anni, mercante di cacao. Viaggio in canoa lungo la costa dello Yucatán fino all’Honduras, e torno con ciò che servono ai signori: cacao, cotone, sale, miele, rame, giada. Un mercante sta più tempo in barca che a casa."],
["Com’è Tulum?","Una città murata su una scogliera alta una dozzina di metri sul mare, con mura spesse su tre lati, un tempio-faro che guida le canoe e un piccolo porto sulla spiaggia. Il suo nome antico, Zamá, vuol dire \"alba\". Ogni mattina il sole sorge proprio davanti alle nostre case."],
["Come si viaggia per mare?","In grandi canoe scavate in un tronco, con una tettoia di foglie al centro per riparare le merci e le persone. A bordo siamo anche venticinque, fra uomini, donne e bambini. Seguiamo la costa, con i fuochi dei fari per orientarci e la barriera corallina da evitare: chi sbaglia rotta paga con un naufragio."],
["Cosa trasportate?","Cacao, balle di cotone, giare di miele, sale, lingotti e campanelle di rame, giada, ossidiana, piume e spade di legno con lame di selce. Dall’Honduras arriva anche cacao di ottima qualità. Il rame, poi, si vende bene perché da noi è raro."],
["Perché il cacao vale tanto?","Perché è il cibo degli dèi e dei signori, e anche una moneta: qualche grano per un pomodoro, qualche centinaio per un tacchino. Si tosta, si macina e si mescola con acqua, peperoncino e miele, poi si versa da un vaso all’altro per farne la schiuma, la parte migliore. Bere cacao è come bere denaro."],
["Come si fanno gli affari?","Al mercato, con la contrattazione, che per noi è un’arte: si parte da un prezzo alto, si scende, ci si arrabbia un po’, si ride, si chiude. Il nostro dio protettore, Ek Chuah, è nero e porta un sacco di mercanzia sulla schiena. Chi si fida troppo di un affare, finisce per pagarlo caro."],
["Cos’è successo vicino a Guanaja nel 1502?","Una grande canoa di mercanti maya, carica di cacao, cotone, rame e armi di legno con lame di selce, incontra navi enormi con uomini in armatura: l’ammiraglio Cristoforo Colombo e suo fratello Bartolomeo, di Genova. I loro uomini la fermano e prendono il carico: il figlio di Colombo, Fernando, racconta del cacao che i mercanti raccoglievano da terra come se fosse un occhio. Per noi era un viaggio come tutti gli altri; per loro, il primo incontro."],
["Cos’è successo nel 1518?","Che dal mare, sulla scogliera, una nave spagnola, quella di Juan de Grijalva, vede la nostra città dipinta di rosso, blu e bianco e dice che è grande come Siviglia, una città che io non conosco. Poi ne vennero altre e, si dice, con loro arrivarono anche malattie nuove: da allora molte famiglie non ci furono più."],
["Cos’è Cozumel e chi è Ixchel?","Un’isola poco a sud, con un santuario della dea Ixchel, che protegge la luna, la fertilità e la tessitura. Le donne maya vengono in pellegrinaggio da tutta la regione, e molte passano da Tulum in canoa. È un viaggio breve, ma impegnativo con il mare mosso."],
["Come ti vesti da mercante?","Un perizoma e un mantello di cotone con strisce colorate, sandali, orecchini di conchiglia e la fascia sulla fronte. I tatuaggi e il corpo dipinto dicono chi sei e da dove vieni. Il mio mantello, per dire, è la mia carta di presentazione."],
["Dove vado dopo?","Sull’altopiano del Guatemala, dove gli antichi conti dei giorni continuano. A Chichicastenango, di notte, i fuochi di copal accendono tutto il cielo e una donna tiene il conto dei 260 giorni. Prendi una coperta: la notte, lassù, è fredda."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che un buon affare è quello in cui tutti e due tornano a casa contenti. Se ripassi, ti offro una tazza di cacao con la schiuma. State bene, e che il mare vi sia calmo!"]
],
my_lucia:[
["Chi sei e che fai?","Lucía, cinquantotto anni, ajq’ij: chi tiene il conto dei giorni. Aiuto le persone a scegliere i giorni giusti per seminare, sposarsi o fare una cerimonia, e a capire il segno con cui sono nate. Di giorno, a volte, vendo anche al mercato: non si vive di sole stelle."],
["Cos’è il calendario di 260 giorni?","Il Cholq’ij: venti segni di giorno che si combinano con i numeri da uno a tredici, e dopo 260 giorni ricomincia da capo. Lo conto da generazioni, e non l’abbiamo mai smesso. Un calendario che si usa ogni giorno è un calendario vivo."],
["Cosa sono i segni dei giorni?","Si chiamano nawales: B’atz’, E, Aj, I’x, Tz’ikin, Ajmaq, No’j, Tijax, Kawoq, Ajpu e così via, fino a venti, ognuno con la propria energia. Ognuno nasce sotto un segno: il mio è un giorno di calma e di ascolto, e ti assicuro che serve. Conoscere il proprio segno è come conoscere il proprio carattere."],
["Come si fa una cerimonia?","Si accende un fuoco con il copal, un incenso, si mettono candele di colori diversi, rosse, nere, bianche e gialle per le quattro direzioni, e si offrono zucchero, fiori e a volte cacao. Si prega ad alta voce, di solito all’alba o al tramonto. È un modo di dire grazie alla terra, al cielo e agli antenati."],
["Cos’è il Popol Vuh?","Il \"Libro del Consiglio\" del nostro popolo, messo per iscritto fra il 1554 e il 1558 da autori K’iche’, nella nostra lingua ma con le lettere latine. Racconta la creazione: gli dèi provano a fare gli esseri umani di fango, poi di legno, e alla fine di mais, e ci riescono. Poi ci sono i Gemelli Eroi, Hunahpú e Xbalanqué, che sfidano i signori di Xibalbá."],
["Dov’è oggi il libro?","Intorno al 1701 un frate domenicano, Francisco Ximénez, parroco di qui, lo copia e lo traduce in spagnolo: dopo vari passaggi, la sua copia arriva nel 1911 alla Newberry Library di Chicago. Molti di noi pensano che un libro debba tornare un po’ a casa: oggi lo si legge anche a scuola, in K’iche’."],
["Cosa successe nel 2012?","Il 21 dicembre 2012 finì il tredicesimo b’ak’tun del Lungo Computo, e molti nel mondo pensarono alla fine del mondo. Per noi era solo l’inizio di un nuovo ciclo: facemmo cerimonie e feste, e il mondo andò avanti. Il calendario era più saggio dei giornali."],
["Com’è la vita oggi?","Coltiviamo ancora la milpa, tessiamo con il telaio a cintura, parliamo K’iche’, e abbiamo anche telefoni, scuole e computer. Siamo milioni di persone, con circa trenta lingue maya. Siamo ancora qui, e non dobbiamo scegliere fra le cose antiche e quelle nuove."],
["Cosa si mangia?","Tortillas calde dal comal, fagioli neri, tamales, zuppe di pollo e verdure, peperoncino e atole la mattina. Il cioccolato lo beviamo ancora, anche se oggi lo zuccheriamo di più. Una tortilla appena fatta è la migliore preghiera del giorno."],
["Come ci si veste?","Con huipil, gonne e fasce tessute a mano su telai a cintura: i motivi dicono da quale villaggio vieni e qualche volta anche chi sei. Per le donne è un vanto, per gli uomini, nei giorni di festa, anche. Un vestito ben tessuto è un libro da leggere."],
["Dove vado dopo?","Guarda a oriente, oltre il vulcano: il cielo comincia a schiarirsi e i fuochi di copal si spengono uno dopo l’altro. È l’alba di un nuovo giorno, e tutto ciò che hai visto oggi continua, fra i campi e il mercato. Vai piano e guarda in alto."],
["Posso salutarti e proseguire la mia passeggiata?","Vai, Pierpaolo, e ricorda che chi tiene il conto dei giorni sa che nessun giorno è uguale all’altro. Se ripassi, ti dico qual è il tuo segno. State bene, e che il sole vi sia propizio!"]
]
};
Object.assign(TOPX,TOPX_MY);
})();
